import re

from django.db import migrations, models
import django.db.models.deletion

_MARKER = re.compile(r"\[whg-dataset:(\d+)\]")

TERMS = [
    # (model, slug, label, sort_order)
    ("ReviewType", "pre-publication-qc", "Pre-publication QC", 15),
    ("ReviewRecommendation", "approved", "Approved", 20),
    ("ReviewRecommendation", "changes-requested", "Changes requested", 25),
    ("ReviewRecommendation", "rejected", "Rejected", 40),
]


def link_uploads(apps, schema_editor):
    TrackedDataset = apps.get_model("grace", "TrackedDataset")
    Dataset = apps.get_model("datasets", "Dataset")
    for row in TrackedDataset.objects.filter(dataset__isnull=True):
        reg = str(row.registry_id or "")
        if reg.startswith("whg:") and reg[4:].isdigit():
            pk = int(reg[4:])
        else:
            m = _MARKER.search(row.notes or "")
            pk = int(m.group(1)) if m else None
        if pk is not None and Dataset.objects.filter(pk=pk).exists():
            # One upload, one tracked record: never link a second row to the same upload.
            if not TrackedDataset.objects.filter(dataset_id=pk).exists():
                TrackedDataset.objects.filter(pk=row.pk).update(dataset_id=pk)


def seed_review_terms(apps, schema_editor):
    for model_name, slug, label, order in TERMS:
        model = apps.get_model("grace", model_name)
        if model.objects.filter(slug=slug).exists():
            continue
        if model.objects.filter(label=label).exists():
            continue  # an editor's term already carries the label; leave it alone
        model.objects.create(slug=slug, label=label, sort_order=order)


